const state={screen:'intro',xp:0,results:{},world:0,mission:0,runtime:{},attempts:0,feedback:null,taskDone:null,selectedToken:null,bossIndex:0,bossChoice:null,bossAction:null,bossAttempts:0,bossFeedback:null,bossDone:false};
let sceneSerial=0,toastTimer;
const answerOrders=new Map();
// Mélanger les indices une fois par question, sans modifier les réponses de référence.
function orderedOptions(options,key){
 if(!answerOrders.has(key)){
  const indices=options.map((_,i)=>i);
  for(let i=indices.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[indices[i],indices[j]]=[indices[j],indices[i]];}
  answerOrders.set(key,indices);
 }
 return answerOrders.get(key).map(index=>({value:options[index],index}));
}
