 const iterator=`<path d="M170 130h300v131H170z" fill="#3b5d7c" stroke="#cae5f1" stroke-width="6"/><path d="M191 100h258v46H191Z" fill="#7a8fae" stroke="#dceaf4" stroke-width="6"/><rect x="210" y="160" width="220" height="75" rx="13" fill="#253556" stroke="${c}" stroke-width="4"/><g font-size="45" text-anchor="middle"><text x="258" y="212">🍄</text><text x="326" y="212">⭐</text><text x="397" y="212">🐢</text></g><path d="M155 71Q320 2 490 74" fill="none" stroke="${c}" stroke-width="8" stroke-dasharray="10 9"/><g class="float-glyph"><circle cx="319" cy="72" r="38" fill="url(#glass${u})"/><path d="M309 56l26 16-28 20" fill="none" stroke="#253653" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"/></g>`;
 return `<svg class="scene-svg" viewBox="0 0 640 390" role="img" aria-label="Illustration du royaume ${escapeText(w.pattern)}" xmlns="http://www.w3.org/2000/svg">${base}<g class="scene-monument">${[strategy,chain,iterator][id]}</g><g fill="${c}"><circle cx="135" cy="118" r="4"/><circle cx="509" cy="124" r="6"/><circle cx="225" cy="54" r="4"/></g></svg>`;
