function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('visible'),2600);}
function burst(symbol='✦'){const e=$('.board')||app,rc=e.getBoundingClientRect();for(let i=0;i<13;i++){const x=document.createElement('span');x.className='burst';x.textContent=symbol;x.style.left=`${rc.left+rc.width/2+(Math.random()-.5)*90}px`;x.style.top=`${rc.top+Math.min(rc.height,220)/2}px`;x.style.setProperty('--dx',`${(Math.random()-.5)*380}px`);x.style.setProperty('--dy',`${-80-Math.random()*155}px`);x.style.setProperty('--rot',`${(Math.random()-.5)*520}deg`);document.body.appendChild(x);setTimeout(()=>x.remove(),1000);}}
function setScreen(s){state.screen=s;render();window.scrollTo(0,0);}
function hud(){return `<header class="hud"><div class="brand"><div class="logo">🧱</div><div><strong>PATTERN BUILDER III</strong><small>LES MÉCANISMES DU COMPORTEMENT</small></div></div><div class="hud-right"><span class="hud-pill">💎 <b>${worlds.filter((_,i)=>allDone(i)).length}/3</b> <em>cristaux</em></span><span class="hud-pill">⭐ <b>${state.xp}</b><em>/${MAX_XP} XP</em> <span class="hud-progress"><i style="width:${100*state.xp/MAX_XP}%"></i></span></span><span class="hud-pill">🏅 Niveau ${Math.min(7,1+Math.floor(state.xp/90))}</span></div></header>`;}
function wrap(content){app.innerHTML=`<div class="shell">${hud()}<div class="content">${content}</div><footer class="footer">🧱 PATTERN BUILDER III · Stratégies, responsabilités et parcours · Hors ligne · Aucune donnée enregistrée</footer></div>`;}
function renderIntro(){wrap(`<section class="splash"><div class="intro"><span class="eyebrow">✦ ÉPISODE III — LA SUITE DE PATTERN BUILDER</span><h1 class="hero-title">Les Mécanismes<br><span class="gradient-text">du Comportement</span></h1><p class="lede">Un dernier dysfonctionnement frappe Patternia ! Les tactiques d’Iron Man se mélangent, les héros ne se transmettent plus les quêtes et les inventaires refusent de s’ouvrir. Répare les trois cristaux en bâtissant et testant de vrais mécanismes.</p><div class="hero-stats"><span>⏱️ 30 minutes</span><span>🧠 3 patrons</span><span>🧩 12 défis + finale</span><span>📐 UML interactif</span></div><div class="btn-row"><button class="btn btn-primary btn-large" data-action="start">▶ Commencer l’aventure</button><button class="btn btn-ghost btn-large" data-action="howto">📖 Comment jouer</button></div><p class="caption" style="margin-top:16px">Chrome / Edge · Pas de connexion Internet · Pas de limite de temps</p></div><div class="hero-art"><div class="art-glow"></div>${sceneSvg(0)}<div class="hero-float-symbols"><span>⚔️</span><span>🔗</span><span>🧭</span></div></div></section><div class="features"><div class="card feature"><span class="feature-icon">🪄</span><h3>Comprendre en manipulant</h3><p>Réalise les opérations, observe les résultats, puis reconstruis les contrats UML du cours.</p></div><div class="card feature"><span class="feature-icon">🎯</span><h3>Deux essais, puis le corrigé</h3><p>Un indice après une première erreur, une explication après la deuxième. Aucune impasse.</p></div><div class="card feature"><span class="feature-icon">🏆</span><h3>Trois nouveaux badges</h3><p>Rétablis les trois cristaux, débloque l’atelier final et obtiens jusqu’à ${MAX_XP} XP.</p></div></div>`);}
function renderHowto(){wrap(`<div class="top-nav"><button class="btn btn-small btn-ghost" data-action="intro">← Accueil</button><span class="crumb">MANUEL DU BÂTISSEUR</span></div><section class="card howto-card"><span class="eyebrow">📖 CONSIGNES</span><h1>Comment jouer ?</h1><div class="howto-grid"><div><h3>🗺️ Choisis ton royaume</h3><p>Strategy → Chain of Responsibility → Iterator. Chaque royaume possède quatre missions progressives ; le suivant se débloque au terme du précédent.</p></div><div><h3>🧱 Construis les diagrammes</h3><p>Glisse les composants UML dans les cases ou sélectionne une pièce puis clique sur son emplacement. Les liens du diagramme se mettent à jour.</p></div><div><h3>⚙️ Lance des simulations</h3><p>Teste plusieurs stratégies, achemine les quêtes, fais avancer des itérateurs et lis les journaux de simulation.</p></div><div><h3>💡 Apprends de tes erreurs</h3><p>Deux tentatives par mission. La première donne un indice ; la deuxième donne une solution expliquée que tu peux appliquer pour continuer.</p></div></div><div class="tip-box">🔎 Aucun chronomètre punitif. Le score reste en mémoire seulement pendant cette partie du navigateur. Actualiser la page recommence la partie.</div><div class="btn-row" style="margin-top:20px"><button class="btn btn-primary" data-action="start">🗺️ Voir les mondes →</button></div></section>`);}
function renderMap(){const count=worlds.filter((_,i)=>allDone(i)).length,canBoss=count===3;
 wrap(`<div class="top-nav"><button class="btn btn-small btn-ghost" data-action="intro">← Accueil</button><span class="crumb">CARTE DE PATTERNIA · ÉPISODE III</span><span class="badge">💎 ${count}/3 cristaux</span></div><section class="map-heading"><span class="eyebrow">🗺️ L’AVENTURE CONTINUE</span><h1>Les trois royaumes</h1><p>Quatre chantiers par patron et un Grand Atelier à réparer. Explore-les dans l’ordre.</p></section><div class="world-grid">${worlds.map((w,i)=>{const unlocked=i===0||allDone(i-1),done=allDone(i);return `<article class="card world-card ${unlocked?'':'locked'} ${done?'completed':''}" style="${themeStyle(i)}"><div class="world-card-art">${sceneSvg(i)}<span class="world-number">MONDE ${i+1}/3</span></div><div class="world-card-body"><div class="world-card-heading"><span class="eyebrow" style="color:var(--world)">${w.pattern.toUpperCase()}</span><span class="badge">${done?'✅ Terminé':unlocked?'🔓 Disponible':'🔒 Verrouillé'}</span></div><h2>${w.name}</h2><p>${w.short}</p><div class="meter-head"><span>Maîtrise</span><span>${Math.round(worldXP(i)/160*100)} %</span></div><div class="meter" style="--mcolor:${w.color}"><i style="width:${worldXP(i)/160*100}%"></i></div><div class="world-card-foot"><span>🎖️ ${w.badge}</span><button class="btn ${unlocked?'btn-primary':'btn-ghost'} btn-small" ${unlocked?'':'disabled'} data-action="open-world" data-world="${i}">${done?'Rejouer ↗':unlocked?'Entrer →':'🔒'}</button></div></div></article>`}).join('')}</div><section class="card boss-map ${canBoss?'boss-open':''}"><div><span class="eyebrow">🏰 LA MISSION FINALE</span><h2>Le Grand Atelier des Mécanismes</h2><p>Trois systèmes défectueux : reconnais le patron approprié et choisis la bonne architecture pour chacun.</p><div class="badge">${canBoss?'✨ Cristaux restaurés, atelier ouvert !':'🔒 Restaurer les trois cristaux pour accéder à la finale'}</div></div><button class="btn btn-gold" data-action="boss-start" ${canBoss?'':'disabled'}>${state.bossDone?'🏆 Revoir le résultat':'⚡ Réparer le cœur'}</button></section>`);}
function initializeRuntime(kind){answerOrders.clear();state.attempts=0;state.feedback=null;state.taskDone=null;state.selectedToken=null;
 switch(kind){
 case 'builder':state.runtime={slots:{},log:[]};break;
 case 'strategySituations':state.runtime={step:0,answers:{},selected:null,log:[]};break;
 case 'strategySequence':state.runtime={stack:[],played:false,log:[]};break;
 case 'strategyConcept':state.runtime={seen:[],choice:null,log:[]};break;
 case 'chainAssemble':state.runtime={placements:{},sent:false,log:[]};break;
 case 'chainQuests':state.runtime={seen:[],log:[]};break;
 case 'chainUnknown':state.runtime={tested:false,choice:null,log:[]};break;
 case 'iteratorWalk':state.runtime={position:0,checked:false,endChecked:false,collected:[],violations:0,log:[]};break;
 case 'iteratorTwin':state.runtime={a:0,b:0,compared:false,log:[]};break;
 case 'iteratorProtocol':state.runtime={placements:{},tested:false,log:[]};break;
 default:state.runtime={log:[]};
 }
}
function openWorld(i){if(i<0||i>=worlds.length||(i>0&&!allDone(i-1)))return;state.world=i;state.mission=worlds[i].tasks.findIndex((_,j)=>!state.results[`${i}-${j}`]);if(state.mission<0)state.mission=0;initializeRuntime(currentTask().kind);setScreen('mission');}
function sidePanel(t){const w=worlds[state.world];return `<aside class="card side-panel"><span class="eyebrow">🧠 LE SAVOIR DU BÂTISSEUR</span><h3>${w.emoji} ${w.pattern}</h3><p>${w.summary}</p><div class="tip-box"><b>🎯 Objectif :</b><br>${escapeText(t.goal)}</div><div class="little-stack">${w.lessons.map((l,i)=>`<div class="lesson-point"><span>${['①','②','③'][i]}</span><span>${escapeText(l)}</span></div>`).join('')}</div><div class="progress-mini"><span>Essais incorrects</span><b>${state.attempts}/2</b></div><div class="meter"><i style="width:${state.attempts*50}%;background:var(--gold)"></i></div><p class="caption">Expérimente librement avant de cliquer sur « Vérifier ». Après deux erreurs, tu recevras une explication détaillée.</p></aside>`;}
function renderMission(){const w=worlds[state.world],t=currentTask(),wi=state.world,mi=state.mission,track=w.tasks.map((_,i)=>`<span class="track-pip ${i===mi?'active':''} ${state.results[`${wi}-${i}`]?'done':''}"></span>`).join('');wrap(`<div class="top-nav"><button class="btn btn-small btn-ghost" data-action="map">← Carte des royaumes</button><div class="crumb">MONDE ${wi+1}/3 &nbsp; › &nbsp; <strong>MISSION ${mi+1}/4</strong></div><span class="badge" style="${themeStyle(wi)}">${w.emoji} ${w.pattern}</span></div><section class="card quest-banner" style="${themeStyle(wi)}"><div><span class="eyebrow" style="color:var(--world)">${w.zone}</span><h1>${w.name}</h1><p>${w.short}</p><div class="quest-track"><span class="caption">Chantiers :</span>${track}<span class="badge">${mi+1}/4</span></div></div><div aria-hidden="true">${sceneSvg(wi)}</div></section><div class="mission-layout" style="${themeStyle(wi)}"><section class="card board"><div class="board-head"><div><span class="mission-kind">⚙️ ${t.tag} · +40 XP MAX</span><h2>${mi+1}. ${t.title}</h2></div><span class="badge goldbadge">🎯 ${mi+1}/4</span></div><p class="board-desc">${t.story}</p>${state.taskDone?taskComplete(t,state.taskDone):renderActivity(t)}</section>${sidePanel(t)}</div>`);}
function taskComplete(t,res){return `<div class="task-complete"><div class="medal">${res.corrected?'📘':'🏆'}</div><span class="eyebrow">${res.corrected?'SOLUTION COMPRISE':'MISSION ACCOMPLIE'}</span><h2>${res.corrected?'Mécanisme réparé !':'Cristal rechargé !'}</h2><div class="xp">+${res.xp} XP ${res.replay?'<span class="caption">(score conservé)</span>':''}</div><p>${t.mastery}</p><div class="feedback lesson" style="text-align:left;max-width:630px;margin:16px auto"><strong>📚 Comprendre la solution</strong><p>${t.explanation}</p></div><button class="btn btn-primary" data-action="next-mission">${state.mission===3?'🌟 Terminer le royaume →':'Prochaine mission →'}</button></div>`;}
function submitBar(extra='🧩 Manipule le mécanisme avant de vérifier.'){return `<div class="action-bar"><div class="mission-stats">${extra}</div><button class="btn btn-primary" data-action="verify" ${state.attempts>=2?'disabled':''}>✅ Vérifier la mission</button></div>${renderFeedback()}`;}
function renderFeedback(){const f=state.feedback;if(!f)return '';return `<div class="feedback ${f.kind==='hint'?'error':'lesson'}" role="alert"><strong>${f.kind==='hint'?'💡 Indice après la première erreur':'📚 Explication après la deuxième erreur'}</strong><p>${f.message}</p>${f.kind==='lesson'?`<p><b>Solution :</b> ${currentTask().explanation}</p><button class="btn btn-gold" data-action="apply-correction">✨ Appliquer la correction et continuer</button>`:''}</div>`;}
const logView=log=>log?.length?`<div class="log" role="log" aria-label="Journal de simulation">${log.slice(-12).map(s=>`<div class="log-row">${escapeText(s)}</div>`).join('')}</div>`:'';
const choiceButtons=(options,selected,action)=>`<div class="choices">${orderedOptions(options,action==='strategy-pick'?`${action}-${state.runtime.step}`:action).map(({value:v,index:i},position)=>`<button class="choice ${selected===i?'selected':''}" data-action="${action}" data-index="${i}" aria-pressed="${selected===i}"><span class="choice-prefix">${String.fromCharCode(65+position)}</span>${escapeText(v)}</button>`).join('')}</div>`;
const simCard=(symbol,title,subtitle,active=false)=>`<div class="sim-card ${active?'glowing':''}"><div class="sim-icon">${symbol}</div><b>${escapeText(title)}</b><small>${escapeText(subtitle)}</small></div>`;
function slotControls(t,field='slots'){const vals=state.runtime[field]||{},selected=state.selectedToken;
 const bank=orderedOptions(t.tokens,`tokens-${field}`).map(({value:token})=>`<button class="token ${selected===token?'selected':''} ${Object.values(vals).includes(token)?'placed':''}" data-action="choose-token" data-token="${escapeText(token)}" draggable="true" aria-pressed="${selected===token}">${escapeText(token)}</button>`).join('');
 const targets=t.slots.map(([label],i)=>`<div class="slot-line"><span class="slot-label">${escapeText(label)}</span><button class="drop-slot ${vals[i]?'filled':''}" data-action="place-slot" data-slot="${i}" aria-label="Emplacement ${i+1}: ${escapeText(label)}"><span>${vals[i]?escapeText(vals[i]):'＋ Déposer une pièce ici'}</span><span class="cross">${vals[i]?'✕':'↓'}</span></button></div>`).join('');return `<p class="caption">Sélectionne une pièce puis clique sur une case, ou glisse la pièce. Clique sur une case remplie sans sélection pour l’effacer.</p><div class="token-bank" role="group" aria-label="Pièces disponibles">${bank}</div><div class="slots">${targets}</div>`;}
function umlDiagram(t){const slots=t.slots,vals=state.runtime.slots,coords=slots.length===4?[[90,25],[445,25],[90,160],[445,160]]:[[290,13],[15,165],[185,165],[357,165],[530,165]];const width=slots.length===4?170:156;
 const nodes=slots.map((slot,i)=>{const [x,y]=coords[i],name=vals[i]||'À compléter';const kind=/^I[A-Z]/.test(name)?'«interface»':name==='QueteHandler'?'«abstraite»':'«classe»';return `<g><rect x="${x}" y="${y}" width="${width}" height="72" rx="10" fill="${vals[i]?'#24565a':'#243755'}" stroke="${vals[i]?'#88f1c9':'#728aae'}" stroke-width="2" ${vals[i]?'':'stroke-dasharray="6 4"'}/><text x="${x+width/2}" y="${y+19}" text-anchor="middle" fill="#a2c3df" font-size="11">${vals[i]?kind:`«rôle ${i+1}»`}</text><text x="${x+width/2}" y="${y+43}" text-anchor="middle" fill="white" font-size="${name.length>17?11:14}" font-weight="bold">${escapeText(name)}</text><line x1="${x+7}" y1="${y+51}" x2="${x+width-7}" y2="${y+51}" stroke="#6f9da6"/><text x="${x+width/2}" y="${y+65}" font-size="9" text-anchor="middle" fill="#b8d5dd">${vals[i]?'✓ Positionné':'À placer'}</text></g>`;}).join('');
 const links=t.relations.map(([from,to,kind,label])=>{if(!vals[from]||!vals[to])return '';const [sx,sy]=coords[from],[tx,ty]=coords[to],x1=sx+width/2,y1=sy+36,x2=tx+width/2,y2=ty+36,dx=x2-x1,dy=y2-y1,len=Math.max(1,Math.hypot(dx,dy)),ex=x2-dx/len*46,ey=y2-dy/len*30;return `<g><line x1="${x1}" y1="${y1}" x2="${ex}" y2="${ey}" stroke="${kind==='association'?'#f8d78c':'#9bd7fa'}" stroke-width="2.7" ${kind!=='association'?'stroke-dasharray="7 5"':''} marker-end="url(#${kind==='association'?'arrow':'triangle'})"/><text x="${(x1+ex)/2}" y="${(y1+ey)/2-6}" fill="#c6e4f0" stroke="#172640" stroke-width="3" paint-order="stroke" text-anchor="middle" font-size="10">${escapeText(label)}</text></g>`;}).join('');
 return `<div class="uml-diagram" role="img" aria-label="Aperçu UML interactif"><div class="diagram-caption">📐 DIAGRAMME UML — les liens apparaissent lorsque les composants sont placés</div><svg viewBox="0 0 720 260" xmlns="http://www.w3.org/2000/svg"><defs><marker id="triangle" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto"><path d="M0 0 L10 5 L0 10Z" fill="#172640" stroke="#9bd7fa" stroke-width="1.5"/></marker><marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto"><path d="M0 1L9 5L0 9" fill="none" stroke="#f8d78c" stroke-width="2"/></marker></defs>${links}${nodes}</svg></div>`;}
const renderBuilder=t=>`${slotControls(t)}${umlDiagram(t)}${submitBar(`${Object.keys(state.runtime.slots).length}/${t.slots.length} rôles placés`)}`;
const ATTACKS=['Laser','Missile','Corps à corps'];
function renderActivity(t){const r=state.runtime;switch(t.kind){
 case 'builder':return renderBuilder(t);
 case 'strategySituations':{const scenarios=[['🎯','Cible très éloignée','Laser'],['🛡️','Blindage lourd','Missile'],['🥊','Ennemi au contact','Corps à corps']];const sc=scenarios[r.step];return `<div class="sim-stage"><div class="sim-chain">${simCard('🦾','IronMan','Contexte : Attaquer()',true)}<span class="sim-arrow">➜</span>${simCard(sc[0],sc[1],r.answers[r.step]!==undefined?`Stratégie : ${ATTACKS[r.answers[r.step]]}`:'Stratégie à choisir',r.answers[r.step]!==undefined)}</div><div class="status-line">${scenarios.map((s,i)=>`<button class="mini-step ${r.step===i?'on':''} ${r.answers[i]!==undefined?'checked':''}" data-action="strategy-step" data-index="${i}">${i+1}. ${s[1]} ${r.answers[i]!==undefined?'✓':''}</button>`).join('')}</div></div><p class="step-label">Quelle stratégie choisir pour cette cible ?</p>${choiceButtons(ATTACKS,r.selected,'strategy-pick')}<div class="controls"><button class="btn btn-gold" data-action="strategy-fire" ${r.selected===null?'disabled':''}>⚡ SetStrategie() → Attaquer()</button></div>${logView(r.log)}${submitBar('Les trois cibles doivent recevoir une stratégie adaptée.')}`;}
 case 'strategySequence':return `<div class="sim-stage"><div class="sim-chain">${simCard('🦾','IronMan','Un seul contexte',true)}<span class="sim-arrow">➜</span>${simCard('🎛️','IAttaque',r.stack.length?`Séquence : ${r.stack.length} attaques`:'Algorithme à remplacer',r.played)}</div><div class="pipeline">${r.stack.length?r.stack.map((n,i)=>`<span>${i+1}. ${escapeText(n)}</span>`).join('<span class="flow-arrow">➜</span>'):'<span>Ajoute tes stratégies ci-dessous…</span>'}</div></div><p class="caption">Construis : Laser → Missile → Corps à corps (trois stratégies consécutives, non simultanées).</p><div class="controls">${orderedOptions(ATTACKS,'seq-add').map(({value:n,index:i})=>`<button class="btn" data-action="seq-add" data-index="${i}" ${r.stack.length>=3?'disabled':''}>${['🔴','🚀','🥊'][i]} ${n}</button>`).join('')}<button class="btn btn-ghost btn-small" data-action="seq-remove" ${!r.stack.length?'disabled':''}>↩ Retirer</button><button class="btn btn-gold" data-action="seq-run" ${r.stack.length!==3?'disabled':''}>▶ Exécuter les attaques</button></div>${logView(r.log)}${submitBar('L’ordre demandé est Laser, Missile, Corps à corps.')}`;
 case 'strategyConcept':return `<div class="sim-stage"><div class="sim-chain">${simCard('🦾','IronMan','inchangé',true)}<span class="sim-arrow">↔</span>${simCard('🎯','IAttaque',`${r.seen.length}/3 variantes observées`,r.seen.length>0)}</div><div class="status-line">${ATTACKS.map((n,i)=>`<button class="mini-step ${r.seen.includes(i)?'checked':''}" data-action="concept-demo" data-index="${i}">${['🔴','🚀','🥊'][i]} Tester ${n} ${r.seen.includes(i)?'✓':''}</button>`).join('')}</div></div>${logView(r.log)}<p class="step-label">Après les tests, quelle est la force de Strategy ?</p>${choiceButtons(['Ajouter toutes les attaques directement dans un gros switch d’IronMan','Séparer les algorithmes derrière IAttaque et les remplacer à l’exécution','Faire hériter IronMan d’une classe différente à chaque attaque'],r.choice,'concept-choice')}${submitBar('Teste les trois variantes et sélectionne l’avantage principal.')}`;
 case 'chainAssemble':{const slots=[['1. Premier gestionnaire','Impa'],['2. Prochain gestionnaire','Navi'],['3. Dernier gestionnaire','Link']];return `<div class="sim-stage"><div class="sim-chain">${[0,1,2].map(i=>simCard(['🛡️','🧚','🗡️'][i],r.placements[i]||'?',`maillon ${i+1}`,Boolean(r.placements[i]))).join('<span class="sim-arrow">➜</span>')}</div></div>${slotControls({tokens:['Link','Impa','Navi'],slots},'placements')}<div class="controls"><button class="btn btn-gold" data-action="chain-start" ${Object.keys(r.placements).length!==3?'disabled':''}>▶ Envoyer « sauver Hyrule »</button></div>${logView(r.log)}${submitBar('Reconstitue Impa → Navi → Link et lance le test.')}`;}
 case 'chainQuests':return `<div class="sim-stage"><div class="sim-chain">${simCard('🛡️','Impa','protéger Zelda',true)}<span class="sim-arrow">➜</span>${simCard('🧚','Navi','donner des indices',true)}<span class="sim-arrow">➜</span>${simCard('🗡️','Link','sauver Hyrule',true)}</div></div><div class="controls">${['protéger Zelda','donner des indices','sauver Hyrule'].map((n,i)=>`<button class="btn ${r.seen.includes(i)?'selected-control':''}" data-action="chain-quest" data-index="${i}">${['🛡️','🧚','🗡️'][i]} ${n} ${r.seen.includes(i)?'✓':''}</button>`).join('')}</div>${logView(r.log)}${submitBar(`${r.seen.length}/3 quêtes envoyées dans la chaîne`)}`;
 case 'chainUnknown':return `<div class="sim-stage"><div class="sim-chain">${simCard('📨','Cuisiner un gâteau','Quête inconnue',true)}<span class="sim-arrow">→</span>${simCard('🔗','Impa → Navi → Link',r.tested?'Aucun responsable trouvé':'En attente',r.tested)}</div></div><div class="controls"><button class="btn btn-gold" data-action="chain-unknown">▶ Envoyer la quête inconnue</button></div>${logView(r.log)}<p class="step-label">Quelle conduite choisir en fin de chaîne ?</p>${choiceButtons(['Boucler indéfiniment sur Impa','Signaler qu’aucun gestionnaire ne peut traiter cette requête','Forcer Link à exécuter n’importe quelle demande'],r.choice,'chain-choice')}${submitBar('Teste le cas sans réponse et sélectionne une gestion appropriée.')}`;
 case 'iteratorWalk':return `<div class="sim-stage"><h3 class="inline-head">🎒 Inventaire privé — parcours séquentiel</h3><div class="item-track">${['🍄 Champignon','⭐ Étoile','🐢 Carapace'].map((n,i)=>`<div class="item-chip ${r.position>i?'collected':''}">${r.position>i?'✅':'🔒'} ${n}</div>`).join('')}</div><div class="status-line"><span class="badge">Position : ${r.position}/3</span><span class="badge">Éléments obtenus : ${r.collected.length}</span><span class="badge">HasNext() final : ${r.endChecked?'false ✓':'à vérifier'}</span></div></div><div class="controls"><button class="btn" data-action="iter-check">🔎 HasNext()</button><button class="btn btn-gold" data-action="iter-next">📦 Next()</button><button class="btn btn-ghost btn-small" data-action="iter-reset">↺ Réinitialiser</button></div>${logView(r.log)}${submitBar('Teste HasNext() avant chaque Next(), puis vérifie la fin.')}`;
 case 'iteratorTwin':return `<div class="sim-stage"><div class="duo-iter"><div class="duo-player"><b>🧑 Explorateur A</b><span>Position ${r.a}/3</span><div class="item-track">${['🍄','⭐','🐢'].map((n,i)=>`<span class="tiny-item ${i<r.a?'collected':''}">${n}</span>`).join('')}</div><button class="btn btn-small" data-action="dual-next" data-value="a" ${r.a>=3?'disabled':''}>Next() de A →</button></div><div class="duo-player"><b>🧙 Explorateur B</b><span>Position ${r.b}/3</span><div class="item-track">${['🍄','⭐','🐢'].map((n,i)=>`<span class="tiny-item ${i<r.b?'collected':''}">${n}</span>`).join('')}</div><button class="btn btn-small" data-action="dual-next" data-value="b" ${r.b>=3?'disabled':''}>Next() de B →</button></div></div></div><div class="controls"><button class="btn btn-gold" data-action="dual-compare">🔎 Comparer les deux positions</button><button class="btn btn-ghost btn-small" data-action="dual-reset">↺ Recommencer</button></div>${logView(r.log)}${submitBar('A doit atteindre 3/3, B 2/3, puis comparer.')}`;
 case 'iteratorProtocol':{const slots=[['Avant la boucle','GetIterator()'],['Condition de la boucle','HasNext()'],['Dans la boucle','Next()']];return `<div class="sim-stage"><div class="sim-chain">${simCard('🎒','Inventaire','Données encapsulées',true)}<span class="sim-arrow">➜</span>${simCard('🧭','Iterator','Parcours séquentiel',r.tested)}</div></div>${slotControls({tokens:['Next()','GetIterator()','HasNext()'],slots},'placements')}<div class="controls"><button class="btn btn-gold" data-action="iter-protocol" ${Object.keys(r.placements).length!==3?'disabled':''}>▶ Exécuter le protocole</button></div>${logView(r.log)}${submitBar('GetIterator() → HasNext() → Next()')}`;}
 default:return `<p>Activité indisponible.</p>`;
 }}
function outcome(){const r=state.runtime,t=currentTask();switch(t.kind){
 case 'builder':return t.slots.every(([,answer],i)=>r.slots[i]===answer);
 case 'strategySituations':return [0,1,2].every((value,i)=>r.answers[i]===value);
 case 'strategySequence':return r.played&&JSON.stringify(r.stack)===JSON.stringify(ATTACKS);
 case 'strategyConcept':return r.seen.length===3&&r.choice===1;
 case 'chainAssemble':return r.sent&&['Impa','Navi','Link'].every((value,i)=>r.placements[i]===value);
 case 'chainQuests':return r.seen.length===3;
 case 'chainUnknown':return r.tested&&r.choice===1;
 case 'iteratorWalk':return r.collected.length===3&&r.endChecked&&r.violations===0;
 case 'iteratorTwin':return r.a===3&&r.b===2&&r.compared;
 case 'iteratorProtocol':return r.tested&&['GetIterator()','HasNext()','Next()'].every((v,i)=>r.placements[i]===v);
 default:return false;
 }}
function isReady(){const r=state.runtime,t=currentTask();switch(t.kind){
 case 'builder':return Object.keys(r.slots).length===t.slots.length;
 case 'strategySituations':return Object.keys(r.answers).length>=1;
 case 'strategySequence':return r.played;
 case 'strategyConcept':return r.seen.length>=1&&r.choice!==null;
 case 'chainAssemble':return r.sent;
 case 'chainQuests':return r.seen.length>=1;
 case 'chainUnknown':return r.tested&&r.choice!==null;
 case 'iteratorWalk':return r.collected.length>=1||r.violations>0;
 case 'iteratorTwin':return r.compared;
 case 'iteratorProtocol':return r.tested;
 default:return false;
 }}
function verify(){if(state.taskDone||state.attempts>=2)return;const t=currentTask();if(!isReady()){toast('🧩 Effectue la simulation ou complète les éléments avant de vérifier.');return;}if(outcome()){finishTask(false);return;}state.attempts++;
 state.feedback=state.attempts===1?{kind:'hint',message:t.hint}:{kind:'lesson',message:'Le mécanisme n’a pas encore satisfait toutes les conditions. Voici le raisonnement et la solution à retenir.'};render();}
function finishTask(corrected=false){const t=currentTask(),k=currentKey(),existing=state.results[k];let xp=0;if(!existing){xp=Math.round(WORLD_XP[state.mission]*(corrected?.55:state.attempts===0?1:.85));state.results[k]={xp,corrected,attempts:state.attempts};state.xp+=xp;}state.taskDone={xp,replay:Boolean(existing),corrected};burst(corrected?'📘':'✨');render();}
function nextMission(){if(state.mission<worlds[state.world].tasks.length-1){state.mission++;initializeRuntime(currentTask().kind);setScreen('mission');}else setScreen('worldComplete');}
function renderWorldComplete(){const w=worlds[state.world],score=worldXP(state.world),next=state.world+1;
 wrap(`<div class="top-nav"><button class="btn btn-small btn-ghost" data-action="map">← Carte des royaumes</button><span class="badge goldbadge">💎 CRISTAL RESTAURÉ</span></div><section class="card world-end" style="${themeStyle(state.world)}"><span class="eyebrow">🌟 MONDE ${state.world+1}/3 TERMINÉ</span><div class="end-crystals">${w.emoji} ✨ 💎</div><h1>${w.name}</h1><h2 class="gradient-text">${w.badge}</h2><p class="lede" style="margin:auto">${w.summary} Tu as terminé les quatre défis du royaume !</p><div class="stats-row"><div class="stat-block"><b>${score}/160</b><small>XP du royaume</small></div><div class="stat-block"><b>4/4</b><small>Missions accomplies</small></div><div class="stat-block"><b>${Math.round(score/160*100)} %</b><small>Maîtrise par XP</small></div></div><div class="btn-row" style="justify-content:center;margin-top:24px"><button class="btn btn-primary" data-action="${next<3?'open-world':'boss-start'}" ${next<3?`data-world="${next}"`:''}>${next<3?'🔓 Découvrir le royaume suivant →':'🏰 Entrer dans le Grand Atelier →'}</button><button class="btn btn-ghost" data-action="map">🗺️ Carte</button></div></section>`);}
function beginBoss(){if(!worlds.every((_,i)=>allDone(i)))return;if(state.bossDone){setScreen('victory');return;}answerOrders.clear();state.bossChoice=null;state.bossAction=null;state.bossAttempts=0;state.bossFeedback=null;setScreen('boss');}
function renderBossFeedback(){const f=state.bossFeedback,b=bossStages[state.bossIndex];if(!f)return '';return `<div class="feedback ${f.kind==='hint'?'error':'lesson'}" role="alert"><strong>${f.kind==='hint'?'💡 Indice de réparation':'📚 Solution expliquée'}</strong><p>${f.message}</p>${f.kind==='lesson'?`<p>${b.detail}</p><button class="btn btn-gold" data-action="boss-fix">✨ Installer la correction</button>`:''}</div>`;}
function renderBoss(){const b=bossStages[state.bossIndex],i=state.bossIndex;wrap(`<div class="top-nav"><button class="btn btn-small btn-ghost" data-action="map">← Carte des royaumes</button><span class="crumb">LE GRAND ATELIER · CRISTAL ${i+1}/3</span><span class="badge goldbadge">+40 XP MAX</span></div><section class="card quest-banner" style="${themeStyle(i)}"><div><span class="eyebrow">🏰 LE CŒUR DE PATTERNIA</span><h1>La grande réparation</h1><p>Trois pannes, trois patrons : remets chaque mécanisme en service avec la bonne architecture.</p><div class="quest-track">${bossStages.map((x,j)=>`<span class="track-pip ${j===i?'active':''} ${j<i?'done':''}"></span>`).join('')}</div></div><div aria-hidden="true">${sceneSvg(i)}</div></section><div class="mission-layout" style="${themeStyle(i)}"><section class="card board"><div class="board-head"><div><span class="mission-kind">⚡ DERNIÈRE ÉPREUVE · ${b.emoji} ${b.part}</span><h2>${i+1}. Réparer le mécanisme</h2></div><span class="badge goldbadge">${i+1}/3</span></div><p class="board-desc">${b.problem}</p><p class="step-label">1. Quel patron utiliser ?</p>${choiceButtons(PATTERNS,state.bossChoice,'boss-pattern')}<p class="step-label">2. Quelle construction est la plus appropriée ?</p>${choiceButtons(b.actions,state.bossAction,'boss-method')}<div class="action-bar"><span class="mission-stats">Essais incorrects : ${state.bossAttempts}/2</span><button class="btn btn-primary" data-action="verify-boss" ${state.bossAttempts>=2?'disabled':''}>⚡ Installer et tester</button></div>${renderBossFeedback()}</section><aside class="card side-panel"><span class="eyebrow">🏰 CŒUR DE PATTERNIA</span><h3>Les trois cristaux</h3><div class="boss-symbol">${b.emoji}</div><p>Identifier le patron ne suffit pas : il faut aussi choisir comment les objets interagissent.</p><div class="little-stack">${bossStages.map((v,j)=>`<div class="lesson-point"><span>${j<i?'✅':j===i?'🛠️':'🔒'}</span><span>${v.part}</span></div>`).join('')}</div></aside></div>`);}
function verifyBoss(){if(state.bossAttempts>=2)return;const b=bossStages[state.bossIndex];if(state.bossChoice===null||state.bossAction===null){toast('🧩 Choisis le patron ET la solution.');return;}if(state.bossChoice===b.pattern&&state.bossAction===b.correctAction){finishBossStage(false);return;}state.bossAttempts++;state.bossFeedback=state.bossAttempts===1?{kind:'hint',message:state.bossChoice!==b.pattern?'Cherche le mécanisme en jeu : algorithme remplaçable, transmission entre gestionnaires ou parcours d’une collection ?':'Tu as trouvé le patron. Réexamine les rôles et la relation entre les objets.'}:{kind:'lesson',message:`Le bon patron est ${PATTERNS[b.pattern]}. La bonne construction est : ${b.actions[b.correctAction]}.`};render();}
function finishBossStage(corrected=false){const i=state.bossIndex,k=`boss-${i}`;if(!state.results[k]){const xp=Math.round(BOSS_XP*(corrected?.55:state.bossAttempts===0?1:.85));state.results[k]={xp,corrected};state.xp+=xp;}state.bossIndex++;answerOrders.clear();state.bossChoice=null;state.bossAction=null;state.bossAttempts=0;state.bossFeedback=null;burst('💎');if(state.bossIndex>=bossStages.length){state.bossDone=true;setScreen('victory');}else setScreen('boss');}
function renderVictory(){const rank=state.xp>=540?'ARCHITECTE LÉGENDAIRE':state.xp>=430?'MAÎTRE DU COMPORTEMENT':'BÂTISSEUR DE PATTERNIA';wrap(`<div class="top-nav"><button class="btn btn-small btn-ghost" data-action="map">← Carte des royaumes</button><span class="badge goldbadge">🏆 AVENTURE TERMINÉE</span></div><section class="card finish-banner"><span class="eyebrow">✨ LES TROIS CRISTAUX SONT RESTAURÉS ✨</span><div class="end-crystals">⚔️ 🔗 🧭</div><h1 class="victory-heading">PATTERNIA<br><span class="gradient-text">EST RECONNECTÉE !</span></h1><p class="lede" style="margin:0 auto">Tu maîtrises les trois mécanismes : changer les algorithmes, faire circuler les requêtes et parcourir une collection.</p><div class="stats-row" style="display:flex;justify-content:center;flex-wrap:wrap;gap:12px;margin:24px 0"><div class="stat-block"><b>${state.xp}/${MAX_XP}</b><small>XP remportés</small></div><div class="stat-block"><b>12/12</b><small>Défis terminés</small></div><div class="stat-block"><b>3/3</b><small>Réparations finales</small></div></div><span class="badge goldbadge">🎖️ ${rank}</span><h2 style="margin:26px 0 13px">Maîtrise des patrons</h2><div class="meter-list" style="max-width:570px;margin:0 auto 28px;text-align:left">${worlds.map((w,i)=>`<div><div class="meter-head"><span>${w.emoji} ${w.pattern}</span><span>${Math.round(worldXP(i)/160*100)} %</span></div><div class="meter" style="--mcolor:${w.color}"><i style="width:${worldXP(i)/160*100}%"></i></div></div>`).join('')}</div><p class="caption">Maîtrise indicative calculée à partir des XP (et non une note certificative). Aucune donnée n’est conservée.</p><div class="btn-row" style="justify-content:center;margin-top:23px"><button class="btn btn-primary" data-action="map">🗺️ Revoir les royaumes</button><button class="btn btn-ghost" data-action="restart">↺ Nouvelle partie</button></div></section>`);}
function render(){switch(state.screen){case 'intro':renderIntro();break;case 'howto':renderHowto();break;case 'map':renderMap();break;case 'mission':renderMission();break;case 'worldComplete':renderWorldComplete();break;case 'boss':renderBoss();break;case 'victory':renderVictory();break;default:renderIntro();}}
function handleAction(action,el){const r=state.runtime,t=state.screen==='mission'?currentTask():null;
 switch(action){
 case 'start':case 'map':setScreen('map');return;
 case 'intro':setScreen('intro');return;
 case 'howto':setScreen('howto');return;
 case 'open-world':openWorld(Number(el.dataset.world));return;
 case 'boss-start':beginBoss();return;
 case 'restart':answerOrders.clear();Object.assign(state,{screen:'intro',xp:0,results:{},world:0,mission:0,runtime:{},attempts:0,feedback:null,taskDone:null,selectedToken:null,bossIndex:0,bossChoice:null,bossAction:null,bossAttempts:0,bossFeedback:null,bossDone:false});render();return;
 case 'verify':verify();return;
 case 'apply-correction':finishTask(true);return;
 case 'next-mission':nextMission();return;
 case 'choose-token':state.selectedToken=state.selectedToken===el.dataset.token?null:el.dataset.token;break;
 case 'place-slot':{
  if(!t)return;const i=Number(el.dataset.slot),field=['chainAssemble','iteratorProtocol'].includes(t.kind)?'placements':'slots',values=r[field];if(!values)return;
  if(state.selectedToken!==null){const value=state.selectedToken;Object.keys(values).forEach(k=>{if(values[k]===value)delete values[k];});values[i]=value;state.selectedToken=null;}else{delete values[i];}
  if(t.kind==='chainAssemble'){r.sent=false;r.log=[];}if(t.kind==='iteratorProtocol'){r.tested=false;r.log=[];}break;
 }
 case 'strategy-step':r.step=Number(el.dataset.index);r.selected=r.answers[r.step]??null;break;
 case 'strategy-pick':r.selected=Number(el.dataset.index);break;
 case 'strategy-fire':{if(r.selected===null)return;r.answers[r.step]=r.selected;const names=['cible distante','blindage lourd','ennemi au contact'];r.log.push(`🦾 IronMan.SetStrategie(new Attaque${r.selected===2?'CorpsACorps':ATTACKS[r.selected]}())`);r.log.push(`⚡ IronMan.Attaquer() → ${ATTACKS[r.selected]} face à ${names[r.step]}`);if(r.step<2){r.step++;r.selected=r.answers[r.step]??null;}break;}
 case 'seq-add':if(r.stack.length>=3)return;r.stack.push(ATTACKS[Number(el.dataset.index)]);r.played=false;r.log=[];break;
 case 'seq-remove':r.stack.pop();r.played=false;r.log=[];break;
 case 'seq-run':r.played=true;r.log=r.stack.flatMap(name=>[`🎛️ SetStrategie(${name==='Corps à corps'?'AttaqueCorpsACorps':'Attaque'+name})`,`⚡ Attaquer() → ${name}`]);break;
 case 'concept-demo':{const i=Number(el.dataset.index);if(!r.seen.includes(i))r.seen.push(i);r.log.push(`🦾 IronMan choisit ${ATTACKS[i]} → exécution de IAttaque.Executer()`);break;}
 case 'concept-choice':r.choice=Number(el.dataset.index);break;
 case 'chain-start':{r.sent=true;const chain=[r.placements[0],r.placements[1],r.placements[2]];r.log=['📨 Demande : sauver Hyrule',...chain.map(n=>n==='Link'?'🗡️ Link : quête traitée !':`${n==='Impa'?'🛡️':'🧚'} ${n} : je transmets la quête.`)];break;}
 case 'chain-quest':{const i=Number(el.dataset.index),queries=['protéger Zelda','donner des indices','sauver Hyrule'],handlers=['Impa','Navi','Link'];if(!r.seen.includes(i))r.seen.push(i);r.log.push(`📨 ${queries[i]} → ${i>=1?'Impa passe → ':''}${i===2?'Navi passe → ':''}${handlers[i]} traite la quête.`);break;}
 case 'chain-unknown':r.tested=true;r.log=['📨 Requête : cuisiner un gâteau','🛡️ Impa → non, je transmets','🧚 Navi → non, je transmets','🗡️ Link → non, plus de successeur','❌ Aucun héros ne peut accomplir cette quête !'];break;
 case 'chain-choice':r.choice=Number(el.dataset.index);break;
 case 'iter-check':{const has=r.position<3;r.checked=has;if(!has)r.endChecked=true;r.log.push(`🔎 HasNext() → ${has?'true':'false'} (position ${r.position}/3)`);break;}
 case 'iter-next':{if(!r.checked||r.position>=3){r.violations++;r.log.push('⚠️ Il faut vérifier HasNext() == true AVANT de consommer Next().');}else{const items=['🍄 Champignon','⭐ Étoile','🐢 Carapace'];r.collected.push(items[r.position]);r.position++;r.checked=false;r.endChecked=false;r.log.push(`📦 Next() → ${items[r.position-1]} (position ${r.position}/3)`);}break;}
 case 'iter-reset':state.runtime={position:0,checked:false,endChecked:false,collected:[],violations:0,log:[]};break;
 case 'dual-next':{const player=el.dataset.value;if(r[player]<3){const items=['🍄 Champignon','⭐ Étoile','🐢 Carapace'];r.log.push(`🧭 Iterator ${player.toUpperCase()}.Next() → ${items[r[player]]}`);r[player]++;r.compared=false;}break;}
 case 'dual-compare':r.compared=true;r.log.push(`🔍 Deux objets itérateurs indépendants : A=${r.a}/3, B=${r.b}/3.`);break;
 case 'dual-reset':state.runtime={a:0,b:0,compared:false,log:[]};break;
 case 'iter-protocol':{r.tested=true;if(['GetIterator()','HasNext()','Next()'].every((v,i)=>r.placements[i]===v)){r.log=['🧭 GetIterator() → InventaireIterator','🔎 HasNext() → true → Next() → 🍄 Champignon','🔎 HasNext() → true → Next() → ⭐ Étoile','🔎 HasNext() → true → Next() → 🐢 Carapace','🔎 HasNext() → false → arrêt de la boucle'];}else{r.log=['❌ Protocole incorrect : commence par obtenir un itérateur puis vérifie avant Next().'];}break;}
 case 'boss-pattern':state.bossChoice=Number(el.dataset.index);break;
 case 'boss-method':state.bossAction=Number(el.dataset.index);break;
 case 'verify-boss':verifyBoss();return;
 case 'boss-fix':finishBossStage(true);return;
 default:return;
 }render();
}
app.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button&&app.contains(button)&&!button.disabled)handleAction(button.dataset.action,button);});
app.addEventListener('dragstart',event=>{const b=event.target.closest('[data-token]');if(!b||!app.contains(b))return;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',b.dataset.token);state.selectedToken=b.dataset.token;});
app.addEventListener('dragover',event=>{const b=event.target.closest('[data-slot]');if(!b)return;event.preventDefault();event.dataTransfer.dropEffect='move';b.classList.add('over');});
app.addEventListener('dragleave',event=>{const b=event.target.closest('[data-slot]');if(b)b.classList.remove('over');});
app.addEventListener('drop',event=>{const b=event.target.closest('[data-slot]');if(!b||state.screen!=='mission')return;const t=currentTask();if(!['builder','chainAssemble','iteratorProtocol'].includes(t.kind))return;event.preventDefault();const token=event.dataTransfer.getData('text/plain');const accepted=t.kind==='builder'?t.tokens:t.kind==='chainAssemble'?['Impa','Navi','Link']:['GetIterator()','HasNext()','Next()'];if(!accepted.includes(token))return;state.selectedToken=token;handleAction('place-slot',b);});
render();
